// Builds src/protection/common-words.ts: the most common words in each browsing
// language, used to warn when a Protected Topic is named with an everyday word.
//
// Source: hermitdave/FrequencyWords (2018 lists, from OpenSubtitles), CC BY-SA 4.0.
// The generated file is a derivative of those lists and carries the same license.
//
// Run: node scripts/build-common-words.mjs

import { writeFileSync } from 'node:fs';

const LANGUAGES = { en: 'English', es: 'Spanish' };
const WORDS_PER_LANGUAGE = 5000;
const source = (code) =>
  `https://raw.githubusercontent.com/hermitdave/FrequencyWords/master/content/2018/${code}/${code}_50k.txt`;

const lists = {};
for (const code of Object.keys(LANGUAGES)) {
  const response = await fetch(source(code));
  if (!response.ok) throw new Error(`${source(code)}: ${response.status}`);
  const lines = (await response.text()).split(/\r?\n/);
  lists[code] = lines
    .map((line) => line.split(' ')[0]?.trim())
    .filter((word) => word && /^\p{L}+$/u.test(word))
    .slice(0, WORDS_PER_LANGUAGE);
}

const body = Object.entries(lists)
  .map(([code, words]) => `  // ${LANGUAGES[code]}\n  ${JSON.stringify(words.join(' '))},`)
  .join('\n');

writeFileSync(
  new URL('../src/protection/common-words.ts', import.meta.url),
  `// Generated by scripts/build-common-words.mjs. Do not edit by hand.
//
// The ${WORDS_PER_LANGUAGE} most common words in each of ${Object.values(LANGUAGES).join(' and ')}, from
// hermitdave/FrequencyWords (https://github.com/hermitdave/FrequencyWords),
// built from OpenSubtitles. Licensed CC BY-SA 4.0
// (https://creativecommons.org/licenses/by-sa/4.0/); this list is a derivative
// and is shared under the same license.

/** Space-separated words, one string per language. */
export const COMMON_WORDS_BY_LANGUAGE: readonly string[] = [
${body}
];
`,
);
console.log(Object.fromEntries(Object.entries(lists).map(([code, words]) => [code, words.length])));
